describe('WebSocket Real-time UI Updates', () => {
  beforeEach(() => {
    cy.visit('/websocket-test');
  });

  it('should establish WebSocket connection and update UI in real-time', () => {
    // Verify initial state
    cy.get('[data-testid="message-list"]').should('be.visible');
    cy.get('[data-testid="message-list"]').should('contain', 'No messages');

    // Intercept WebSocket connection
    cy.intercept('GET', '/api/websocket').as('websocketConnect');

    // Trigger WebSocket connection
    cy.get('[data-testid="connect-button"]').click();

    // Wait for WebSocket connection
    cy.wait('@websocketConnect');

    // Verify connection is established
    cy.get('[data-testid="connection-status"]').should('be.visible');
    cy.get('[data-testid="connection-status"]').should('contain', 'Connected');

    // Verify UI updates with real-time data
    cy.get('[data-testid="message-list"]').should('contain', 'Welcome to WebSocket Test');
    cy.get('[data-testid="message-list"]').should('contain', 'Initial message');

    // Verify WebSocket message is received and displayed
    cy.get('[data-testid="message-list"]').should('contain', 'Real-time message');

    // Verify WebSocket disconnect button works
    cy.get('[data-testid="disconnect-button"]').click();

    // Wait for WebSocket disconnect
    cy.wait('@websocketDisconnect');

    // Verify connection is closed
    cy.get('[data-testid="connection-status"]').should('contain', 'Disconnected');

    // Verify UI updates to reflect disconnection
    cy.get('[data-testid="message-list"]').should('contain', 'Disconnected');
  });

  it('should handle WebSocket connection errors and update UI accordingly', () => {
    // Intercept WebSocket connection with error
    cy.intercept('GET', '/api/websocket', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('websocketError');

    // Attempt to connect
    cy.get('[data-testid="connect-button"]').click();

    // Wait for error
    cy.wait('@websocketError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'WebSocket connection failed');

    // Verify UI does not update with real-time data
    cy.get('[data-testid="message-list"]').should('not.contain', 'Real-time message');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify retry button works
    cy.get('[data-testid="retry-button"]').click();

    // Wait for WebSocket connection to retry
    cy.wait('@websocketConnect');

    // Verify connection is re-established
    cy.get('[data-testid="connection-status"]').should('contain', 'Reconnected');

    // Verify UI updates with real-time data
    cy.get('[data-testid="message-list"]').should('contain', 'Reconnected');
  });
});
